{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Test bounded training-frequency midrank percentiles instead of standardized log counts across all four category models. Preserve padding and mask scales at 1; the existing checkpoint buffer and predictor retain the computed scales without architecture changes.",
      "edits": [
        {
          "find": "    log_counts = np.log1p(training_counts[1:itemnum + 1])\n    standardized_counts = (log_counts - log_counts.mean()) / max(float(log_counts.std()), 1e-6)\n    input_scales = 1.0 + 0.02 * np.tanh(standardized_counts)",
          "replace": "    real_counts = training_counts[1:itemnum + 1]\n    _, count_inverse, tie_counts = np.unique(\n        real_counts, return_inverse=True, return_counts=True\n    )\n    midpoint_percentiles = (\n        np.cumsum(tie_counts, dtype=np.float64) - 0.5 * tie_counts\n    ) / float(itemnum)\n    frequency_percentiles = midpoint_percentiles[count_inverse]\n    input_scales = 1.0 + 0.02 * (2.0 * frequency_percentiles - 1.0)"
        }
      ]
    }
  ],
  "change_summary": "Replace log-frequency modulation with tie-aware frequency percentile modulation using training interactions only. Existing checkpoint and predictor plumbing remains compatible."
}
